UPDATE c2k_source
SET name = #{source.name}, locator = #{source.locator}, branch = #{source.branch}, enabled = #{source.enabled}, revision = revision + 1
WHERE tenant_id = #{source.tenantId} AND id = #{source.id} AND revision = #{source.revision} AND kind = #{source.kind}
